        final_db_path,
        "SELECT id, sender_id, sender_role, content, created_at FROM messages WHERE booking_id = ? ORDER BY created_at DESC",
        ('BKG-7788',)
    )

    # Check if a new message was added
    if len(final_messages) != len(initial_messages) + 1:
        return {"result": "others"}

    # Verify we have exactly 3 messages now (2 initial + 1 new)
    if len(final_messages) != 3:
        return {"result": "others"}

    # Get the new message (should be the first one in descending order)
    new_message = None
