    try:
        db_path = os.path.join(tmpdir, f"{sn}.db")
        conn = sqlite3.connect(db_path)
        cur = conn.cursor()
        for table in db_schema.get("tables", []):
            try:
                cur.execute(table["ddl"])
                for idx_sql in table.get("indexes", []):
