        shutil.copy2(db_path, final_path)
        os.chmod(init_path, 0o444)
        os.chmod(final_path, 0o444)

        issues = []
        for idx, v in by_scen.get(sn, []):
            code = v.get("verification", {}).get("code", "")
            task_idx = v.get("task_idx")
            if not code or not isinstance(code, str) or len(code.strip()) < 10:
                issues.append(("empty_code", idx, task_idx, "Empty code"))
                continue
            func_name = "verify_task_completion"
            for line in code.split("\n"):
                line_s = line.strip()
                if line_s.startswith("def verify_") and "(" in line_s:
                    func_name = line_s.split("(")[0].replace("def ", "").strip()
                    break
            for test_ans in ["", "Completed successfully. Here are the results: 1, 2, 3, true, active, confirmed."]:
                try:
                    ns = {"sqlite3": sqlite3, "json": json, "os": os, "re": re, "__builtins__": __builtins__}
                    exec(code, ns)
                    vf = ns.get(func_name)
                    if not vf:
                        issues.append(("no_func", idx, task_idx, f"No func {func_name}"))
                        break
                    res = _call_verifier_func(vf, init_path, final_path, test_ans)
                    if not isinstance(res, dict) or "result" not in res:
                        issues.append(("bad_ret", idx, task_idx, f"Bad return: {res}"))
                        break
                    if res.get("result") == "complete":
                        issues.append((f"complete_on_initial(ans={bool(test_ans)})", idx, task_idx, res))
                        break
                except Exception as e:
                    issues.append(("exception_on_initial", idx, task_idx, str(e)))
                    break
        return sn, issues
    finally:
        shutil.rmtree(tmpdir, ignore_errors=True)

all_issues = []
with ProcessPoolExecutor(max_workers=16) as ex:
    for sn, issues in ex.map(check_scenario, sorted(by_scen.keys())):
        for iss in issues:
            all_issues.append((sn, *iss))

from collections import Counter
print("Total issues found:", len(all_issues))
print("By type:", Counter(x[1] for x in all_issues))
for x in all_issues[:30]:
    print(x)
