python3 - << 'EOF'
import json, sqlite3, tempfile, os
import pyarrow.parquet as pq

t = pq.read_table('/workspace/data/AgentWorldModel-1K/verl/test.parquet').to_pylist()
test_tasks = [r['env_kwargs'] for r in t]
test_scenarios = {x['scenario'] for x in test_tasks}

db_map = {}
with open('/workspace/data/AgentWorldModel-1K/gen_db.jsonl') as f:
    for line in f:
        obj = json.loads(line)
        if obj['scenario'] in test_scenarios:
            db_map[obj['scenario']] = obj['db_schema']

sample_map = {}
with open('/workspace/data/AgentWorldModel-1K/gen_sample.jsonl') as f:
    for line in f:
        obj = json.loads(line)
        if obj['scenario'] in test_scenarios:
            sample_map[obj['scenario']] = obj['sample_data']

def build_db(scenario, path):
    conn = sqlite3.connect(path)
    cur = conn.cursor()
    for tbl in db_map[scenario]['tables']:
        cur.execute(tbl['ddl'])
        for idx_sql in tbl.get('indexes', []):
            cur.execute(idx_sql)
        for ex_sql in tbl.get('examples', []):
            try:
                cur.execute(ex_sql)
            except Exception:
                pass
    conn.commit()
    cur.execute("PRAGMA foreign_keys = ON;")
    for tbl in sample_map[scenario].get('tables', []):
        for stmt in tbl.get('insert_statements', []):
            try:
                cur.execute(stmt)
            except Exception:
                pass
    conn.commit()
    conn.close()

with tempfile.TemporaryDirectory() as tmpdir:
    def q(sc, sql, params=()):
        p = os.path.join(tmpdir, f"{sc}.db")
        if not os.path.exists(p):
            build_db(sc, p)
        conn = sqlite3.connect(p)
        res = conn.execute(sql, params).fetchall()
        conn.close()
        return res

    for sc in ['marketplace_21', 'booking_reservations_14', 'analytics_dashboard_1', 'task_management_17', 'dating_matchmaking_4']:
        if sc not in db_map: continue
        print(f"=== {sc} ===")
        for tbl in db_map[sc]['tables']:
            print(" ", tbl['name'], q(sc, f"SELECT * FROM {tbl['name']}"))
EOF

