file.content:
import ast
import json
import pathlib
import textwrap

ROOT = pathlib.Path('/workspace')
BASE = pathlib.Path('/tmp/staged-experiment-repair')
PATCHES = {}


def rule(key, body):
    code = ('def verify_task_completion(initial_db_path: str, final_db_path: str, '
            'final_answer: str | None = None) -> dict:\n'
            '    import sqlite3\n    import json\n    import re\n    import math\n'
            '    from contextlib import closing\n\n'
            '    def query(path, sql, params=()):\n'
            '        with closing(sqlite3.connect(f"file:{path}?mode=ro", uri=True)) as conn:\n'
            '            return conn.execute(sql, params).fetchall()\n\n'
            '    try:\n' + textwrap.indent(textwrap.dedent(body).strip(), '        ') + '\n'
            '    except (sqlite3.Error, ValueError, TypeError, KeyError, IndexError, AttributeError):\n'
            '        # Missing or malformed evidence cannot prove task completion.\n'
            '        return {"result": "others"}\n')
    ast.parse(code)
    PATCHES[key] = code


rule(('stock_trading_1', 2), '''
# A requested new watchlist must be created during this episode. A seeded
# list, an unrelated write, or adding items to an old list is insufficient.
initial_ids = {r[0] for r in query(initial_db_path, "SELECT id FROM watchlists")}
required = {'MSFT', 'NVDA', 'AMD', 'AVGO', 'META'}
for (watchlist_id,) in query(final_db_path,
        "SELECT id FROM watchlists WHERE user_id = ? AND name = ?",
        (1, 'Tech Growth 2025')):
    if watchlist_id in initial_ids:
        continue
    symbols = {r[0] for r in query(final_db_path,
        "SELECT s.symbol FROM watchlist_items wi JOIN securities s "
        "ON s.id = wi.security_id WHERE wi.watchlist_id = ?", (watchlist_id,))}
    if symbols == required:
        return {"result": "complete"}
return {"result": "others"}
''')

rule(('asset_management_6', 1), '''
# Histories for both the vehicle and driver read this shared assignment table.
# A seeded equivalent row must neither satisfy a no-op nor invalidate a new
# successful assignment created during the episode.
initial_ids = {r[0] for r in query(initial_db_path, "SELECT id FROM asset_driver_assignments")}
assignments = query(final_db_path,
    "SELECT ada.id FROM asset_driver_assignments ada "
    "JOIN assets a ON a.id = ada.asset_id JOIN drivers d ON d.id = ada.driver_id "
    "WHERE a.license_plate = ? AND d.full_name = ? "
    "AND ada.start_date = ? AND ada.end_date = ? AND ada.created_by = 1",
    ('ABC-1234', 'Maria Lopez', '2025-01-05', '2025-01-10'))
if any(assignment_id not in initial_ids for (assignment_id,) in assignments):
    return {"result": "complete"}
return {"result": "others"}
''')

rule(('discussion_forum_2', 0), '''
initial_ids = {r[0] for r in query(initial_db_path, "SELECT id FROM threads")}
threads = query(final_db_path,
    "SELECT t.id FROM threads t JOIN communities c ON c.id = t.community_id "
    "JOIN categories cat ON cat.id = t.category_id AND cat.community_id = c.id "
    "WHERE c.name = ? AND cat.name = ? AND t.title = ? "
    "AND t.creator_user_id = 1 AND t.status = 'open'",
    ('Brookside Neighborhood', 'Events', 'Saturday Park Cleanup Volunteers Needed'))
for (thread_id,) in threads:
    if thread_id in initial_ids:
        continue
    tags = {r[0].lower() for r in query(final_db_path,
        "SELECT tg.name FROM thread_tags tt JOIN tags tg ON tg.id = tt.tag_id "
        "WHERE tt.thread_id = ?", (thread_id,))}
    if tags != {'volunteer', 'park', 'cleanup'}:
        continue
    posts = query(final_db_path,
        "SELECT content FROM posts WHERE thread_id = ? AND position = 1 "
        "AND user_id = 1 AND is_hidden = 0", (thread_id,))
    for (content,) in posts:
        text = (content or '').lower()
        time_ok = re.search(r'9\s*(?:a\.?m\.?)?\s*[-–—]\s*11\s*a\.?m\.?', text)
        if ('saturday' in text and 'brookside park' in text and time_ok
                and any(w in text for w in ('trash', 'cleanup', 'pick'))
                and any(w in text for w in ('reply', 'interest', 'join', 'volunteer'))):
            return {"result": "complete"}
return {"result": "others"}
''')

rule(('logistics_and_shipment_tracking_1', 0), '''
initial_ids = {r[0] for r in query(initial_db_path, "SELECT id FROM shipments")}
shipments = query(final_db_path,
    "SELECT sh.id, sh.status, sh.declared_value, sh.length_cm, sh.width_cm, "
    "sh.height_cm, sh.weight_kg FROM shipments sh "
    "JOIN merchants m ON m.id = sh.merchant_id "
    "JOIN carriers c ON c.id = sh.carrier_id "
    "JOIN service_levels sl ON sl.id = sh.service_level_id AND sl.carrier_id = c.id "
    "WHERE m.merchant_code = ? AND m.user_id = 1 AND c.carrier_code = ? "
    "AND sl.service_code = ? AND sh.order_reference = ?",
    ('acme_store', 'fastship', 'standard_ground', 'ACME-ORD-1001'))
for shipment_id, status, *values in shipments:
    if shipment_id in initial_ids or status != 'created':
        continue
    if any(v is None or not math.isfinite(float(v)) or abs(float(v) - expected) > 0.01
           for v, expected in zip(values, (79.99, 30.0, 20.0, 10.0, 2.5))):
        continue
    addresses = query(final_db_path,
        "SELECT address_line, city, region, postal_code, country "
        "FROM shipment_addresses WHERE shipment_id = ? AND address_type = 'delivery'",
        (shipment_id,))
    if ('123 Market St', 'San Francisco', 'CA', '94103', 'US') in addresses:
        return {"result": "complete"}
return {"result": "others"}
''')

rule(('iot_device_management_3', 5), '''
from datetime import datetime, timezone, timedelta

def utc(value):
    parsed = datetime.fromisoformat(value.replace('Z', '+00:00'))
    return (parsed.replace(tzinfo=timezone.utc) if parsed.tzinfo is None
            else parsed.astimezone(timezone.utc))

initial_firmware_ids = {r[0] for r in query(initial_db_path, "SELECT id FROM firmware_versions")}
initial_job_ids = {r[0] for r in query(initial_db_path, "SELECT id FROM firmware_update_jobs")}
required_models = {'vm-COOLER-200', 'vm-COOLER-300'}
start = datetime(2026, 1, 2, 1, tzinfo=timezone.utc)
for (firmware_id,) in query(final_db_path,
        "SELECT id FROM firmware_versions WHERE version_code = ? AND release_channel = ?",
        ('2.3.5', 'stable')):
    if firmware_id in initial_firmware_ids:
        continue
    compatible = {r[0] for r in query(final_db_path,
        "SELECT device_model_id FROM firmware_version_compatibility "
        "WHERE firmware_version_id = ?", (firmware_id,))}
    if compatible != required_models:
        continue
    jobs = query(final_db_path,
        "SELECT id, rollout_start_at, rollout_end_at, target_device_model_id, state "
        "FROM firmware_update_jobs WHERE firmware_version_id = ? "
        "AND release_channel = 'stable' AND target_site_type = 'factory' "
        "AND target_device_status = 'active'", (firmware_id,))
    for job_id, job_start, job_end, model_filter, state in jobs:
        if job_id in initial_job_ids or model_filter is not None:
            continue
        if state != 'scheduled':
            continue
        if utc(job_start) == start and utc(job_end) == start + timedelta(hours=3):
            return {"result": "complete"}
return {"result": "others"}
''')

rule(('booking_and_reservations_3', 3), '''
# Higher numbers mean higher priority in this scenario; the seeded high
# priority party uses level 5. Both newly created rows must be linked.
initial_walk_ids = {r[0] for r in query(initial_db_path, "SELECT id FROM walk_ins")}
