import json, pathlib, sqlite3, collections, warnings
warnings.filterwarnings('ignore', category=SyntaxWarning)
ROOT=pathlib.Path('/workspace'); BASE=pathlib.Path('/tmp/staged-experiment-repair')
keys={tuple(k) for k in json.loads((BASE/'rollout_tasks.json').read_text())}; scenarios={k[0] for k in keys}
records={}
for name in ['gen_db','gen_sample']:
 records[name]={r['scenario']:r for r in map(json.loads,(ROOT/'data/AgentWorldModel-1K'/f'{name}.jsonl').open()) if r['scenario'] in scenarios}
verifiers={}
for r in map(json.loads,(BASE/'original_rules.jsonl').open()):verifiers.setdefault((r['scenario'],r['task_idx']),r)
for sc in sorted(scenarios):
 d=BASE/sc;d.mkdir(exist_ok=True);p=d/'seed.db'
 if p.exists():p.unlink()
 con=sqlite3.connect(p);errors=[]
 for table in records['gen_db'][sc]['db_schema']['tables']:
  for sql in [table['ddl'],*table.get('indexes',[]),*table.get('examples',[])]:
   try:con.execute(sql)
   except sqlite3.Error as e:errors.append(str(e))
 con.commit();con.execute('PRAGMA foreign_keys = ON')
 for table in records['gen_sample'][sc]['sample_data']['tables']:
  for sql in table['insert_statements']:
   try:con.execute(sql)
   except sqlite3.Error as e:errors.append(str(e))
 con.commit();con.close()
 print(sc,'seed errors',len(errors),list(dict.fromkeys(errors))[:3])
for key in sorted(keys):
 p=BASE/key[0]/'seed.db';ns={};r=verifiers[key]
 try:
  exec(r['verification']['code'],ns)
  out=ns['verify_task_completion'](str(p),str(p),'I could not complete the requested task. No actions were performed.')
 except Exception as e:out={'error':str(e)}
 print('NO-OP',key,out)
print('FROZEN FINALS ON UNCHANGED SEED')
taskkeys={r['task']:k for k,r in verifiers.items() if k in keys}
for file in sorted((ROOT/'logs/rollouts').glob('*.jsonl')):
 groups=collections.defaultdict(list)
 for r in map(json.loads,file.open()):groups[r['traj_uid']].append(r)
 for uid,rs in groups.items():
  rs.sort(key=lambda r:r['step_num']);key=next((k for t,k in taskkeys.items() if t in rs[0]['obs_text_base']),None)
  if key is None:continue
  p=BASE/key[0]/'seed.db';ns={}
  try:
   exec(verifiers[key]['verification']['code'],ns)
   out=ns['verify_task_completion'](str(p),str(p),rs[-1]['output'])
  except Exception as e:out={'error':str(e)}
