arguments.command:
python3 -c '
import json, collections, pathlib

ROOT = pathlib.Path("/workspace")
tasks = {}
with open(ROOT / "data/AgentWorldModel-1K/gen_tasks.jsonl") as f:
    for l in f:
        d = json.loads(l)
        for ti, t in enumerate(d["tasks"]):
            tasks[t] = (d["scenario"], ti)

for step in [1, 150, 175, 190, 199, 200]:
    groups = collections.defaultdict(list)
    for r in map(json.loads, (ROOT / "logs/rollouts" / f"{step}.jsonl").open()):
        groups[r["traj_uid"]].append(r)
    for uid, rs in groups.items():
        rs.sort(key=lambda r: r["step_num"])
        matched = [k for t, k in tasks.items() if t in rs[0]["obs_text_base"]]
        print(f"Step {step} | uid {uid} | len={len(rs)} | score={rs[-1][\"score\"]} | task={matched}")
        for r in rs:
            print(f"   step_num={r[\"step_num\"]}: output={repr(r[\"output\"][:140])}")
'

