import ast
import json
import pathlib
import textwrap

ROOT = pathlib.Path('/workspace')
BASE = pathlib.Path('/tmp/staged-experiment-repair')
PATCHES = {}


def rule(key, body):
    code = ('def verify_task_completion(initial_db_path: str, final_db_path: str, '
            'final_answer: str | None = None) -> dict:\n'
            '    import sqlite3\n    import json\n    import re\n    import math\n'
            '    from contextlib import closing\n\n'
            '    def query(path, sql, params=()):\n'
            '        with closing(sqlite3.connect(f"file:{path}?mode=ro", uri=True)) as conn:\n'
            '            return conn.execute(sql, params).fetchall()\n\n'
            '    try:\n' + textwrap.indent(textwrap.dedent(body).strip(), '        ') + '\n'
            '    except (sqlite3.Error, ValueError, TypeError, KeyError, IndexError, AttributeError):\n'
            '        # Missing or malformed evidence cannot prove task completion.\n'
            '        return {"result": "others"}\n')
    ast.parse(code)
    PATCHES[key] = code


