    ('Paid Social Campaigns', 'Email Campaigns'))
board_ids = {board_id for board_id, name in boards}
if {name for board_id, name in boards} != {'Paid Social Campaigns', 'Email Campaigns'} or len(board_ids) != 2:
    return {"result": "others"}
columns = query(final_db_path,
    "SELECT id, board_id, name FROM columns WHERE name IN ('Status', 'Start Date', 'End Date')")
required_columns = {name: {cid for cid, bid, colname in columns if bid in board_ids and colname == name}
                    for name in ('Status', 'Start Date', 'End Date')}

def ids(values):
    return {int(v) for v in values}

for (dashboard_id,) in query(final_db_path,
        "SELECT id FROM dashboards WHERE name = ? AND created_by = 1",
        ('Marketing Campaign Overview',)):
    if dashboard_id in initial_ids:
        continue
    linked = {r[0] for r in query(final_db_path,
        "SELECT board_id FROM dashboard_boards WHERE dashboard_id = ?", (dashboard_id,))}
    if linked != board_ids:
        continue
    found = set()
    for widget_type, settings_text in query(final_db_path,
            "SELECT widget_type, settings_json FROM widgets WHERE dashboard_id = ?", (dashboard_id,)):
        try:
            settings = json.loads(settings_text)
            if not isinstance(settings, dict) or ids(settings.get('boards', [])) != board_ids:
                continue
            if widget_type == 'numbers':
                if (str(settings.get('status_value', '')).lower() == 'launched'
                        and str(settings.get('metric', 'count')).lower() == 'count'
                        and required_columns['Status'].issubset(ids(settings.get('status_column_ids', [])))):
                    found.add('numbers')
            elif widget_type == 'chart':
                if (str(settings.get('group_by', '')).lower() == 'status'
