                    found.add('chart')
            elif widget_type == 'timeline':
                statuses = {str(v).lower() for v in settings.get('filter_status', [])}
                if (required_columns['Start Date'].issubset(ids(settings.get('start_date_columns', [])))
                        and required_columns['End Date'].issubset(ids(settings.get('end_date_columns', [])))
                        and statuses and statuses <= {'planned', 'scheduled', 'launched', 'active', 'in progress'}):
                    found.add('timeline')
        except (ValueError, TypeError, AttributeError):
            continue
    if found == {'numbers', 'chart', 'timeline'}:
