    # Currency/total labels, or a table cell immediately following the name.
    amount_patterns = [r'\$\s*(\d+(?:\.\d+)?)',
        r'(?:total[_\s]*raised|raised|amount)\s*[=:]?\s*\$?\s*(\d+(?:\.\d+)?)',
        re.escape(name) + r'\s*\|\s*\$?\s*(\d+(?:\.\d+)?)']
    amounts = [float(m.group(1)) for p in amount_patterns for m in re.finditer(p, segment, re.I)]
    if not amounts or any(abs(v - float(amount)) > 0.01 for v in amounts):
        return {"result": "others"}
    count_patterns = [r'(?:donation[_\s]*count|num[_\s]*donations|donations?)\s*[=:]?\s*(\d+)\b',
                      r'\b(\d+)\s+donations?\b']
    counts = [int(m.group(1)) for p in count_patterns for m in re.finditer(p, segment, re.I)]
    ranks = [int(m.group(1)) for m in re.finditer(r'\brank\s*[#=:]?\s*(\d+)\b', segment, re.I)]
    prefix = segment[:segment.lower().find(name.lower())]
    numbered = re.search(r'^\s*(?:[-*]\s*)?#?(\d+)\s*[.)|:–—-]', prefix)
    if numbered:
        ranks.append(int(numbered[1]))
    if '|' in segment:
        # Markdown columns: Rank | Member | Total raised | Donations.
        cells = [c.strip() for c in segment.split('|') if c.strip()]
        name_index = next((j for j, cell in enumerate(cells) if name.lower() == cell.lower()), -1)
        if name_index >= 1 and cells[name_index-1].isdigit():
            ranks.append(int(cells[name_index-1]))
        if name_index >= 0 and len(cells) > name_index + 2 and cells[name_index+2].isdigit():
            counts.append(int(cells[name_index+2]))
    if not counts or any(v != int(count) for v in counts) or not ranks or any(v != i+1 for v in ranks):
