    for opening in re.finditer(r'[\[{]', structured_text):
        try:
            value, _ = decoder.raw_decode(structured_text[opening.start():])
        except ValueError:
            continue
        if isinstance(value, (dict, list)):
            obj = value
            break
if isinstance(obj, dict):
    obj = obj.get('match_candidates', obj.get('candidates', obj.get('candidate_user_ids', obj.get('results'))))
if isinstance(obj, list):
    if len(obj) != len(rows):
        return {"result": "others"}
    for item, (cid, distance, score) in zip(obj, rows):
        # An ordered list of candidate IDs also returns the requested list.
        if isinstance(item, (int, str)) and str(item).isdigit():
            if int(item) != cid:
                return {"result": "others"}
