    for cells, (cid, distance, score) in zip(table_rows, rows):
        if not cells[0].isdigit() or int(cells[0]) != cid:
            return {"result": "others"}
        numeric = [float(v) for cell in cells[1:] for v in re.findall(r'\d+(?:\.\d+)?', cell)]
        if not any(abs(v - score) < 0.001 for v in numeric):
