    distances = re.findall(r'(?i)["\x27]?distance(?:[_\s]+miles)?["\x27]?\s*[:=]?\s*(\d+(?:\.\d+)?)', segment)
    if scores and any(abs(float(v) - score) > 0.001 for v in scores):
