        noop_complete.append((idx, sc, tidx, task))
    elif out_echo.get("result") == "complete":
        echo_complete.append((idx, sc, tidx, task))

print(f"Test tasks completing on NO-OP ({len(noop_complete)}):")
for idx, sc, tidx, task in noop_complete:
    print(f"  [{idx}] {sc}#{tidx}: {task[:100]}")

print(f"Test tasks completing on ECHO ({len(echo_complete)}):")
for idx, sc, tidx, task in echo_complete:
