TASK: As a clinic admin, generate an invoice for booking ID 'BK-2101' using the appointment type fee, apply a 10% discount code 'NEWPATIENT10', set tax to 8%, mark the payment status as 'unpaid', and schedule an automatic payment reminder notification 3 days before the due date.
CODE:
def verify_task_completion(initial_db_path: str, final_db_path: str, final_answer: str | None = None) -> dict:
    import sqlite3
    from datetime import datetime, timedelta

    def safe_query(db_path: str, query: str, params: tuple = ()) -> list:
        try:
            conn = sqlite3.connect(f"file:{db_path}?mode=ro", uri=True)
            cursor = conn.cursor()
            cursor.execute(query, params)
            results = cursor.fetchall()
            conn.close()
            return results
        except Exception:
            return []

    # Get invoice for BK-2101 from final database
    invoice_query = """
        SELECT id, booking_id, base_amount, discount_code_id, discount_amount, 
               tax_rate, tax_amount, total_amount, status, due_at
        FROM invoices 
        WHERE booking_id = ?
    """
    invoice_results = safe_query(final_db_path, invoice_query, ('BK-2101',))

    if not invoice_results:
        return {"result": "others"}

    invoice = invoice_results[0]
    invoice_id = invoice[0]
    booking_id = invoice[1]
    base_amount = invoice[2]
    discount_code_id = invoice[3]
    discount_amount = invoice[4]
    tax_rate = invoice[5]
    tax_amount = invoice[6]
    total_amount = invoice[7]
    status = invoice[8]
    due_at_str = invoice[9]

    # Verify booking_id
    if booking_id != 'BK-2101':
        return {"result": "others"}

    # Verify base_amount (should be 150.0 from appointment_types)
    if abs(base_amount - 150.0) > 0.01:
        return {"result": "others"}

    # Verify discount_code_id (1 for NEWPATIENT10)
    if discount_code_id != 1:
        return {"result": "others"}

    # Verify discount_amount (10% of 150.0 = 15.0)
    if abs(discount_amount - 15.0) > 0.01:
        return {"result": "others"}

    # Verify tax_rate (8%)
    if abs(tax_rate - 8.0) > 0.01:
        return {"result": "others"}

    # Verify tax_amount calculation: 8% of (150.0 - 15.0) = 8% of 135.0 = 10.8
    expected_tax_amount = (base_amount - discount_amount) * (tax_rate / 100.0)
    if abs(tax_amount - expected_tax_amount) > 0.01:
        return {"result": "others"}

    # Verify total_amount calculation: 150.0 - 15.0 + 10.8 = 145.8
    expected_total = base_amount - discount_amount + tax_amount
    if abs(total_amount - expected_total) > 0.01:
        return {"result": "others"}

    # Verify status is 'unpaid'
    if status != 'unpaid':
        return {"result": "others"}

    # Get invoice_notifications for this invoice
    notification_query = """
        SELECT id, invoice_id, notification_type, scheduled_at
        FROM invoice_notifications 
        WHERE invoice_id = ? AND notification_type = ?
    """
    notification_results = safe_query(final_db_path, notification_query, (invoice_id, 'payment_reminder'))

    if not notification_results:
        return {"result": "others"}

    notification = notification_results[0]
    notification_invoice_id = notification[1]
    notification_type = notification[2]
    scheduled_at_str = notification[3]

    # Verify notification_type
    if notification_type != 'payment_reminder':
        return {"result": "others"}

    # Verify notification_invoice_id matches
    if notification_invoice_id != invoice_id:
        return {"result": "others"}

    # Parse dates and verify scheduled_at is 3 days before due_at
    try:
        # Handle different datetime formats
        for fmt in ['%Y-%m-%d %H:%M:%S', '%Y-%m-%d %H:%M:%S.%f', '%Y-%m-%d']:
            try:
                due_at = datetime.strptime(due_at_str.split('.')[0], fmt)
                break
            except ValueError:
                continue
        else:
            return {"result": "others"}

        for fmt in ['%Y-%m-%d %H:%M:%S', '%Y-%m-%d %H:%M:%S.%f', '%Y-%m-%d']:
            try:
                scheduled_at = datetime.strptime(scheduled_at_str.split('.')[0], fmt)
                break
            except ValueError:
                continue
        else:
            return {"result": "others"}

        # Calculate expected scheduled date (3 days before due date)
        expected_scheduled = due_at - timedelta(days=3)

        # Check if scheduled_at is within same day as expected (allow time flexibility)
        if scheduled_at.date() != expected_scheduled.date():
            return {"result": "others"}

    except Exception:
        return {"result": "others"}

    # All checks passed
    return {"result": "complete"}

