TASK: Retrieve all completed bookings where I am the sitter for the past 30 days, calculate the total earnings and platform_fees from booking_items, and generate a summary of payouts grouped by payout_id.
CODE:
def verify_task_completion(initial_db_path: str, final_db_path: str, final_answer: str | None = None) -> dict:
    import sqlite3
    import re

    def safe_query(db_path: str, query: str, params: tuple = ()) -> list:
        try:
            conn = sqlite3.connect(f"file:{db_path}?mode=ro", uri=True)
            cursor = conn.cursor()
            cursor.execute(query, params)
            results = cursor.fetchall()
            conn.close()
            return results
        except Exception:
            return []

    # Check if final_answer exists
    if not final_answer or not isinstance(final_answer, str) or len(final_answer.strip()) < 20:
        return {"result": "others"}

    final_answer_lower = final_answer.lower()

    # Check for key concepts related to the task
    has_completed = 'completed' in final_answer_lower or 'complete' in final_answer_lower
    has_earnings = 'earning' in final_answer_lower or 'earn' in final_answer_lower
    has_fees = 'fee' in final_answer_lower or 'platform' in final_answer_lower
    has_payout = 'payout' in final_answer_lower
    has_sitter = 'sitter' in final_answer_lower
    has_booking = 'booking' in final_answer_lower

    # Must have at least earnings/fees and payout concepts
    if not (has_earnings or has_fees):
        return {"result": "others"}

    if not has_payout:
        return {"result": "others"}

    # Look for numeric values that could represent earnings or fees
    # Pattern to match currency amounts like $55.25, 55.25, $120.00, etc.
    money_pattern = r'\$?\d+\.\d{2}|\$?\d+'
    numbers = re.findall(money_pattern, final_answer)

    if len(numbers) < 2:
        # Need at least 2 numbers (some earnings and fees)
        return {"result": "others"}

    # Extract numeric values for validation
    numeric_values = []
    for num_str in numbers:
        cleaned = num_str.replace('$', '').replace(',', '')
        try:
            numeric_values.append(float(cleaned))
        except ValueError:
            continue

    if len(numeric_values) < 2:
        return {"result": "others"}

    # Query the database to get expected values for any sitter with completed bookings
    # We need to check if the numbers in final_answer could match any sitter's data
    query = '''
    SELECT 
        pi.payout_id,
        SUM(pi.sitter_earnings) as total_earnings,
        SUM(pi.platform_fees) as total_fees
    FROM payout_items pi
    JOIN payouts p ON pi.payout_id = p.id
    GROUP BY pi.payout_id
    '''

    payout_data = safe_query(final_db_path, query)

    if not payout_data:
        # No payout data exists, check if answer indicates no results
        no_results_indicators = ['no booking', 'no completed', 'no record', '0 booking', 'zero booking', 'empty', 'none found']
        if any(indicator in final_answer_lower for indicator in no_results_indicators):
            return {"result": "complete"}
        return {"result": "others"}

    # Check if any of the numeric values in final_answer match expected database values
    expected_values = set()
    for payout_id, earnings, fees in payout_data:
        if earnings is not None:
            expected_values.add(float(earnings))
        if fees is not None:
            expected_values.add(float(fees))
        if earnings is not None and fees is not None:
            expected_values.add(float(earnings) + float(fees))

    # Check if at least 2 numbers from final_answer match expected values (with tolerance)
    matches = 0
    for num in numeric_values:
        for expected in expected_values:
            if abs(num - expected) < 0.01:  # Allow small floating point differences
                matches += 1
                break

    if matches >= 2:
        # Check for payout grouping/summary structure
        # Look for payout_id mentions or structured grouping
        payout_id_pattern = r'payout[_\s]*(id)?[_\s]*:?[_\s]*\d+'
        has_payout_id = bool(re.search(payout_id_pattern, final_answer_lower))

        # Or look for grouping indicators
        grouping_indicators = ['group', 'summary', 'total', 'payout 1', 'payout 2', 'payout_id']
        has_grouping = any(indicator in final_answer_lower for indicator in grouping_indicators)

        if has_payout_id or has_grouping:
            return {"result": "complete"}

    # Alternative: Check if the answer describes the structure even without exact matches
    # (for cases where formatting differs but content is correct)
    structure_indicators = [
        'grouped by payout',
        'payout_id',
        'per payout',
        'each payout',
        'summary of payout'
    ]

    has_structure = any(indicator in final_answer_lower for indicator in structure_indicators)

    if has_structure and len(numeric_values) >= 4:
        # Has structure mention and multiple numbers (likely earnings + fees for multiple payouts)
        return {"result": "complete"}

    return {"result": "others"}

