def verify_task_completion(initial_db_path: str, final_db_path: str, final_answer: str | None = None) -> dict:
    import sqlite3
    import re

    def safe_query(db_path: str, query: str, params: tuple = ()) -> list:
        try:
            conn = sqlite3.connect(f"file:{db_path}?mode=ro", uri=True)
            conn.row_factory = sqlite3.Row
            cursor = conn.cursor()
            cursor.execute(query, params)
            results = cursor.fetchall()
            conn.close()
            return results
        except Exception:
            return []

    # Find the sales_analysis task for 2023
    tasks = safe_query(final_db_path, 
        "SELECT id, task_type, status FROM tasks WHERE task_type = 'sales_analysis' AND status = 'completed'"
    )

    if not tasks:
        return {"result": "others"}

    # Get the task_id (should be 2 based on the dump)
    task_id = None
    for task in tasks:
        # Check if this is the 2023 sales analysis
        task_id = task['id']
        break

    if not task_id:
        return {"result": "others"}

    # Check if analysis_tasks record exists with meaningful explanation
    analysis_tasks = safe_query(final_db_path,
        "SELECT id, overall_explanation FROM analysis_tasks WHERE task_id = ?",
        (task_id,)
    )

    if not analysis_tasks:
        return {"result": "others"}

    analysis_task = analysis_tasks[0]
    analysis_id = analysis_task['id']
    overall_explanation = analysis_task['overall_explanation']

    # Verify explanation exists and has meaningful content (at least 50 chars)
    if not overall_explanation or len(overall_explanation.strip()) < 50:
        return {"result": "others"}

    # Check for exactly 3 top predictors with ranks 1, 2, 3
    predictors = safe_query(final_db_path,
        "SELECT importance_rank, variable_name, description, correlation_coefficient FROM analysis_predictors WHERE analysis_id = ? AND importance_rank <= 3 ORDER BY importance_rank",
        (analysis_id,)
    )

    if len(predictors) != 3:
        return {"result": "others"}

    # Verify the predictors have ranks 1, 2, 3
    expected_ranks = {1, 2, 3}
    actual_ranks = {p['importance_rank'] for p in predictors}
    if actual_ranks != expected_ranks:
        return {"result": "others"}

    # Verify each predictor has required fields
    for predictor in predictors:
        if not predictor['variable_name'] or len(predictor['variable_name'].strip()) == 0:
            return {"result": "others"}
        if not predictor['description'] or len(predictor['description'].strip()) < 10:
            return {"result": "others"}
        if predictor['correlation_coefficient'] is None:
            return {"result": "others"}

    # Check for Q1 2024 recommendations
    recommendations = safe_query(final_db_path,
        "SELECT recommendation_text, period FROM analysis_recommendations WHERE analysis_id = ?",
        (analysis_id,)
    )

    if not recommendations:
        return {"result": "others"}

    # Verify at least one recommendation mentions Q1 2024
    q1_2024_found = False
    for rec in recommendations:
        period = rec['period'] or ''
        recommendation_text = rec['recommendation_text'] or ''

        # Check if period mentions Q1 2024 or similar variations
        if re.search(r'Q1\s*2024|2024\s*Q1|Jan.*2024|February.*2024|March.*2024|first quarter.*2024', period, re.IGNORECASE):
            q1_2024_found = True

        # Verify recommendation has meaningful content
        if len(recommendation_text.strip()) < 20:
            return {"result": "others"}

    if not q1_2024_found:
        return {"result": "others"}

    # All checks passed
    return {"result": "complete"}

