            results = cursor.fetchall()
            conn.close()
            return results
        except Exception:
            return []

    if not final_answer or len(final_answer.strip()) < 50:
        return {"result": "others"}

    final_answer_lower = final_answer.lower()

    required_muscle_groups = ['chest', 'back', 'legs', 'shoulders', 'arms']
    muscle_groups_found = 0
    for mg in required_muscle_groups:
        if mg in final_answer_lower:
            muscle_groups_found += 1

    if muscle_groups_found < 5:
        return {"result": "others"}

    metrics_patterns = [
        r'\b(total\s+)?sets?\b',
        r'\b(total\s+)?reps?\b',
        r'\b(total\s+)?weight\b|\b(total\s+)?lifted\b|\bkg\b|\blbs?\b'
    ]
    metrics_found = 0
    for pattern in metrics_patterns:
        if re.search(pattern, final_answer_lower):
            metrics_found += 1

    if metrics_found < 2:
        return {"result": "others"}

    week_patterns = [
        r'week\s*[1-4]',
        r'week\s+(?:one|two|three|four)',
        r'\d{4}-\d{2}-\d{2}.*\d{4}-\d{2}-\d{2}'
    ]
    week_mentions = 0
    for pattern in week_patterns:
        matches = re.findall(pattern, final_answer_lower)
        week_mentions += len(matches)

    if week_mentions < 3:
