        r'20%|twenty percent',
        r'increase|decrease|change',
        r'highlight|flag|notable|significant',
        r'\b\d+%\s*(increase|decrease|change)',
        r'(increase|decrease|change)\s*of\s*\d+%'
    ]
    change_found = False
    for pattern in change_patterns:
        if re.search(pattern, final_answer_lower):
            change_found = True
            break

    if not change_found:
