        return {"result": "others"}

    initial_count = len(initial_records)
    final_count = len(final_records)
    new_count = final_count - initial_count

    # Must have exactly 50 new records
    if new_count != 50:
        return {"result": "others"}

    # Get the IDs from initial records to identify new ones
    initial_ids = {row[0] for row in initial_records}
    new_records = [(row[0], row[1]) for row in final_records if row[0] not in initial_ids]

    if len(new_records) != 50:
        return {"result": "others"}

    # Calculate actual distribution of new records
    band_90_100 = 0
    band_80_89 = 0
    band_70_79 = 0
    band_below_70 = 0

    for record_id, score in new_records:
        if score is None or not (0 <= score <= 100):
            return {"result": "others"}

        if 90 <= score <= 100:
            band_90_100 += 1
        elif 80 <= score <= 89:
            band_80_89 += 1
        elif 70 <= score <= 79:
            band_70_79 += 1
        else:
            band_below_70 += 1

    # Verify final_answer contains the summary
    if not final_answer or len(final_answer.strip()) == 0:
        return {"result": "others"}

    # Extract counts from final_answer for each band
    # Looking for patterns like "90-100: 15" or "90 to 100: 15" or "90-100 score band: 15"
    patterns = [
        (r"90[-\s]*(?:to|[-])?[-\s]*100[^\d]*(\d+)", band_90_100),
        (r"80[-\s]*(?:to|[-])?[-\s]*89[^\d]*(\d+)", band_80_89),
        (r"70[-\s]*(?:to|[-])?[-\s]*79[^\d]*(\d+)", band_70_79),
        (r"below[-\s]*70[^\d]*(\d+)", band_below_70)
    ]

    matched_counts = 0
    for pattern, expected_count in patterns:
        matches = re.findall(pattern, final_answer, re.IGNORECASE)
        if matches:
            try:
                extracted_count = int(matches[0])
                if extracted_count == expected_count:
                    matched_counts += 1
            except (ValueError, IndexError):
                continue

    # All 4 bands must be reported correctly
    if matched_counts == 4:
        return {"result": "complete"}

    # Alternative pattern: check if numbers appear in the same order as bands
    # Extract all numbers from final_answer
    all_numbers = re.findall(r"\b\d+\b", final_answer)
    if len(all_numbers) >= 4:
        # Try to find a sequence matching our expected distribution
        expected_sequence = [band_90_100, band_80_89, band_70_79, band_below_70]
        for i in range(len(all_numbers) - 3):
            try:
                sequence = [int(all_numbers[i]), int(all_numbers[i+1]), int(all_numbers[i+2]), int(all_numbers[i+3])]
