    # Get today's date for comparison
    today = datetime.now().date()
    today_str = today.strftime('%Y-%m-%d')

    # Calculate expected due date (14 days from today)
    expected_due_date = today + timedelta(days=14)
    expected_due_date_str = expected_due_date.strftime('%Y-%m-%d')

    # Step 1: Identify users with expired Forklift Safety Certification
    expired_query = """
        SELECT uc.user_id, u.full_name, u.username, d.name as department_name, 
               uc.expiry_date, e.completion_date, c.title
        FROM user_certifications uc
        JOIN certifications cert ON uc.certification_id = cert.id
        JOIN users u ON uc.user_id = u.id
        LEFT JOIN departments d ON u.department_id = d.id
        LEFT JOIN enrollments e ON uc.last_completion_enrollment_id = e.id
        LEFT JOIN courses c ON cert.associated_course_id = c.id
        WHERE cert.title = 'Forklift Safety Certification'
        AND uc.expiry_date < ?
    """

    expired_users = safe_query(initial_db_path, expired_query, (today_str,))

    if not expired_users:
        # No expired certifications found - task cannot be completed
        return {"result": "others"}

    expired_user_ids = [row[0] for row in expired_users]

    # Step 2: Verify final_answer contains report information
    if not final_answer:
        return {"result": "others"}

    # Check if final_answer mentions the key elements of the report
    # Should contain user information and expired certification details
    report_checks = 0

    # Check for at least some user names or identifiers
    for user_id, full_name, username, dept, expiry, completion, course_title in expired_users:
        # Look for user name or username in report
        if full_name and re.search(re.escape(full_name), final_answer, re.IGNORECASE):
            report_checks += 1
            break
        if username and re.search(re.escape(username), final_answer, re.IGNORECASE):
            report_checks += 1
            break

    # Check for department information
    for user_id, full_name, username, dept, expiry, completion, course_title in expired_users:
        if dept and re.search(re.escape(dept), final_answer, re.IGNORECASE):
            report_checks += 1
            break

    # Check for mention of expiry or certification
    if re.search(r'expir(ed|y)', final_answer, re.IGNORECASE):
        report_checks += 1

    if re.search(r'forklift', final_answer, re.IGNORECASE):
        report_checks += 1

    # Require at least 3 of these checks to pass
    if report_checks < 3:
        return {"result": "others"}

    # Step 3: Verify new enrollment records in final_db
