test_df = pd.read_parquet('/workspace/data/AgentWorldModel-1K/verl/test.parquet')
verifiers = {}
with open('/tmp/staged-experiment-repair/original_rules.jsonl') as f:
    for line in f:
        d = json.loads(line)
        key = (d['scenario'], d['task_idx'])
        if key not in verifiers:
            verifiers[key] = d

class ReachedFinalDB(Exception):
    pass

for idx, row in test_df.iterrows():
    tk = row['env_kwargs']
    s = tk['scenario']
    t = int(tk['task_idx'])
    v = verifiers[(s, t)]
    code = v['verification']['code']
    # Replace safe_query's `except Exception:` with `except sqlite3.Error:` so ReachedFinalDB propagates!
    mod_code = code.replace('except Exception:', 'except sqlite3.Error:')
    mod_code = mod_code.replace('sqlite3.connect', '_wrapped_connect')
    ns = {}
    orig_connect = sqlite3.connect
    def _wrapped_connect(uri, *args, **kwargs):
        if 'FINAL_SENTINEL' in str(uri):
            raise ReachedFinalDB()
        return orig_connect(uri, *args, **kwargs)
    ns['_wrapped_connect'] = _wrapped_connect
    exec(mod_code, ns)
    fn = ns['verify_task_completion']
    db_path = f'/tmp/test_seeds/{idx}_{s}_{t}.db'
    try:
        res = fn(db_path, 'FINAL_SENTINEL', tk['task'] + " Yes Completed 100")
        if 'final_db_path' in code.split('):', 1)[1]:
            print(f"[{idx}] {s}#{t} returned BEFORE touching final_db_path: {res}")
    except ReachedFinalDB:
        pass
    except Exception as e:
        print(f"[{idx}] {s}#{t} raised {type(e).__name__}: {e}")
EOF

