    num_to_shortlist = min(5, len(initial_new_suggestions))

    # Get the top 5 (or fewer) by compatibility_score
    top_5_ids = [row[0] for row in initial_new_suggestions[:num_to_shortlist]]
    other_ids = [row[0] for row in initial_new_suggestions[num_to_shortlist:]]

