TASK: Generate and retrieve a weekly volume and intensity report for the last 4 weeks showing total sets, total reps, and total lifted weight per muscle group (chest, back, legs, shoulders, arms) and highlight any muscle group with more than a 20% change in volume week-over-week.
def verify_task_completion(initial_db_path: str, final_db_path: str, final_answer: str | None = None) -> dict:
    import sqlite3
    import re
    from datetime import datetime, timedelta

    def safe_query(db_path: str, query: str, params: tuple = ()) -> list:
        try:
            conn = sqlite3.connect(f"file:{db_path}?mode=ro", uri=True)
            cursor = conn.cursor()
            cursor.execute(query, params)
            results = cursor.fetchall()
            conn.close()
            return results
        except Exception:
            return []

    if not final_answer or len(final_answer.strip()) < 50:
        return {"result": "others"}

    final_answer_lower = final_answer.lower()

    required_muscle_groups = ['chest', 'back', 'legs', 'shoulders', 'arms']
    muscle_groups_found = 0
    for mg in required_muscle_groups:
        if mg in final_answer_lower:
            muscle_groups_found += 1

    if muscle_groups_found < 5:
        return {"result": "others"}

    metrics_patterns = [
        r'\b(total\s+)?sets?\b',
        r'\b(total\s+)?reps?\b',
        r'\b(total\s+)?weight\b|\b(total\s+)?lifted\b|\bkg\b|\blbs?\b'
    ]
    metrics_found = 0
    for pattern in metrics_patterns:
        if re.search(pattern, final_answer_lower):
            metrics_found += 1

    if metrics_found < 2:
        return {"result": "others"}

    week_patterns = [
        r'week\s*[1-4]',
        r'week\s+(?:one|two|three|four)',
        r'\d{4}-\d{2}-\d{2}.*\d{4}-\d{2}-\d{2}'
    ]
    week_mentions = 0
    for pattern in week_patterns:
        matches = re.findall(pattern, final_answer_lower)
        week_mentions += len(matches)

    if week_mentions < 3:
        return {"result": "others"}

    change_patterns = [
        r'20%|twenty percent',
        r'increase|decrease|change',
        r'highlight|flag|notable|significant',
        r'\b\d+%\s*(increase|decrease|change)',
        r'(increase|decrease|change)\s*of\s*\d+%'
    ]
    change_found = False
    for pattern in change_patterns:
        if re.search(pattern, final_answer_lower):
            change_found = True
            break

    if not change_found:
        return {"result": "others"}

    query = """
    SELECT mg.name, 
           COUNT(DISTINCT ss.id) as total_sets,
           SUM(CASE WHEN ss.reps IS NOT NULL THEN ss.reps ELSE 0 END) as total_reps,
           SUM(CASE WHEN ss.weight IS NOT NULL AND ss.reps IS NOT NULL THEN ss.weight * ss.reps ELSE 0 END) as total_weight
    FROM workout_sessions ws
    JOIN session_exercises se ON ws.id = se.session_id
    JOIN session_sets ss ON se.id = ss.session_exercise_id
    JOIN exercises e ON se.exercise_id = e.id
    JOIN exercise_muscle_groups emg ON e.id = emg.exercise_id
    JOIN muscle_groups mg ON emg.muscle_group_id = mg.id
    WHERE ws.user_id = 1
      AND ws.start_time IS NOT NULL
      AND ss.is_warmup = 0
      AND mg.name IN ('Chest', 'Back', 'Legs', 'Shoulders', 'Arms')
    GROUP BY mg.name
    """

    db_results = safe_query(final_db_path, query)

    if len(db_results) == 0:
        return {"result": "others"}

    db_muscle_groups_with_data = set()
    for row in db_results:
        muscle_name = row[0].lower()
        total_sets = row[1]
        if total_sets > 0:
            db_muscle_groups_with_data.add(muscle_name)

    answer_has_data_match = False
    for mg in db_muscle_groups_with_data:
        if mg in final_answer_lower:
            number_pattern = r'\b\d+\b'
            numbers_near_mg = re.findall(number_pattern, final_answer_lower[max(0, final_answer_lower.index(mg)-100):final_answer_lower.index(mg)+200])
            if len(numbers_near_mg) >= 2:
                answer_has_data_match = True
                break

    if not answer_has_data_match:
        return {"result": "others"}

    return {"result": "complete"}
