    # Get today's date for comparison
    today = datetime.now().date()
    today_str = today.strftime('%Y-%m-%d')

    # Calculate expected due date (14 days from today)
    expected_due_date = today + timedelta(days=14)
    expected_due_date_str = expected_due_date.strftime('%Y-%m-%d')

    # Step 1: Identify users with expired Forklift Safety Certification
    expired_query = """
        SELECT uc.user_id, u.full_name, u.username, d.name as department_name, 
               uc.expiry_date, e.completion_date, c.title
        FROM user_certifications uc
        JOIN certifications cert ON uc.certification_id = cert.id
        JOIN users u ON uc.user_id = u.id
        LEFT JOIN departments d ON u.department_id = d.id
        LEFT JOIN enrollments e ON uc.last_completion_enrollment_id = e.id
        LEFT JOIN courses c ON cert.associated_course_id = c.id
        WHERE cert.title = 'Forklift Safety Certification'
        AND uc.expiry_date < ?
    """

