            break

    if not change_found:
        return {"result": "others"}

    query = """
    SELECT mg.name, 
           COUNT(DISTINCT ss.id) as total_sets,
           SUM(CASE WHEN ss.reps IS NOT NULL THEN ss.reps ELSE 0 END) as total_reps,
           SUM(CASE WHEN ss.weight IS NOT NULL AND ss.reps IS NOT NULL THEN ss.weight * ss.reps ELSE 0 END) as total_weight
