    placeholders = ','.join('?' * len(expired_user_ids))
    initial_enrollments_query = f"""
        SELECT user_id, id, created_at, due_date, assignment_reason
        FROM enrollments 
        WHERE course_id = ? AND user_id IN ({placeholders})
    """

