                                     (forklift_course_id,) + tuple(expired_user_ids))
    initial_enrollment_ids = set(row[1] for row in initial_enrollments)

    # Check final enrollments for these users
    final_enrollments = safe_query(final_db_path, initial_enrollments_query, 
                                   (forklift_course_id,) + tuple(expired_user_ids))

    # Identify new enrollments (present in final but not in initial)
    new_enrollments = [row for row in final_enrollments if row[1] not in initial_enrollment_ids]

    if not new_enrollments:
        return {"result": "others"}

    # Step 4: Validate each new enrollment
    new_enrollment_user_ids = set()
    for user_id, enroll_id, created_at, due_date, assignment_reason in new_enrollments:
        # Check assignment_reason is 'mandatory'
        if assignment_reason != 'mandatory':
            return {"result": "others"}

        # Check due_date is approximately 14 days from today (allow 1 day tolerance)
        if due_date:
            try:
                due_date_obj = datetime.strptime(due_date, '%Y-%m-%d').date()
                days_diff = (due_date_obj - today).days
                if not (13 <= days_diff <= 15):
                    return {"result": "others"}
            except ValueError:
                return {"result": "others"}
        else:
            return {"result": "others"}

        new_enrollment_user_ids.add(user_id)

    # Step 5: Ensure all expired users got reassigned
    if not set(expired_user_ids).issubset(new_enrollment_user_ids):
        return {"result": "others"}

    # All checks passed
    return {"result": "complete"}
