    initial_balance = 0
    for trans_type, amount in initial_transactions:
        if trans_type == 'order_earning':
            initial_balance += amount
        elif trans_type == 'payout':
            initial_balance += amount  # amount is already negative

    # Available balance should be positive
    if initial_balance <= 0:
        return {"result": "others"}

    # Get initial payouts for user_id=1
    initial_payouts = safe_query(
