    db_path = f'/tmp/test_seeds/{s}.db'
    orig_connect = sqlite3.connect
    queries = []
    class TracingCursor:
        def __init__(self, cur, is_init):
            self.cur = cur
            self.is_init = is_init
        def execute(self, sql, params=()):
            self.last_sql = sql
            self.last_params = params
            return self.cur.execute(sql, params)
        def fetchall(self):
            res = self.cur.fetchall()
            if self.is_init:
                queries.append((self.last_sql.strip(), self.last_params, res))
            return res
        def fetchone(self):
            res = self.cur.fetchone()
            if self.is_init:
                queries.append((self.last_sql.strip(), self.last_params, res))
            return res
        def __getattr__(self, name):
            return getattr(self.cur, name)
    class TracingConn:
        def __init__(self, conn, is_init):
            self.conn = conn
            self.is_init = is_init
        def cursor(self):
            return TracingCursor(self.conn.cursor(), self.is_init)
        def close(self):
            return self.conn.close()
        def __getattr__(self, name):
