        is_init = '/./' not in str(uri)
        return TracingConn(orig_connect(uri, *args, **kwargs), is_init)
    ns = {'_tracing_connect': _tracing_connect}
    exec(mod_code, ns)
    fn = ns['verify_task_completion']
    try:
